solution.code:
function buatState(build, awal) {
  const s = {
    state: awal,
    tampilan: build(awal),
    jumlahBuild: 1,
    mounted: true,
    setState(fn) {
      if (!s.mounted) throw new Error("setState dipanggil setelah dispose");
      fn(s.state);
      s.tampilan = build(s.state);
      s.jumlahBuild++;
    },
    dispose() {
      s.mounted = false;
    },
  };
  return s;
}

