solution.code:
function buatNavigator(awal) {
  const isi = [{ layar: awal, tiket: null }];
  return {
    push(layar) {
      const tiket = { selesai: false, hasil: undefined };
      isi.push({ layar, tiket });
      return tiket;
    },
    pop(hasil) {
      if (isi.length === 1) return;
      const { tiket } = isi.pop();
      tiket.selesai = true;
      tiket.hasil = hasil;
    },
    puncak() {
      return isi[isi.length - 1].layar;
    },
    tumpukan() {
      return isi.map((x) => x.layar);
    },
  };
}

