function naikkanVersi(versi, jenis) {
  const m = /^(\d+)\.(\d+)\.(\d+)\+(\d+)$/.exec(versi);
  if (!m) throw new Error("Format versi salah");
  let [major, minor, patch, build] = m.slice(1).map(Number);
  if (jenis === "major") {
    major++;
    minor = 0;
    patch = 0;
  } else if (jenis === "minor") {
    minor++;
    patch = 0;
  } else if (jenis === "patch") {
    patch++;
  } else if (jenis !== "build") {
    throw new Error("Jenis tidak dikenal");
  }
  return `${major}.${minor}.${patch}+${build + 1}`;
}
